#!/usr/bin/env python3
"""Wraps the WebAssembly file as base64 in a small script, so pages work
from file:// as well (no fetch). Same input gives the same output."""
import base64, hashlib, sys
wasm = open(sys.argv[1], 'rb').read()
b64 = base64.b64encode(wasm).decode()
sha = hashlib.sha256(wasm).hexdigest()[:12]
open(sys.argv[2], 'w').write(
    '/* Generated by ada/build.sh from ada/src (Ada language core). Do not edit.\n'
    f'   {len(wasm)} bytes of WebAssembly, sha256 {sha}. */\n'
    f'window.__UIM_WASM={{size:{len(wasm)},sha:"{sha}",b64:"{b64}"}};\n')
